# Languages with valid BCP 47 codes — used for hreflang alternate tags and sitemap.
# Fun/novelty languages are intentionally excluded: unknown hreflang values cause
# Google Search Console errors.
REAL_LANGS: frozenset = frozenset({
    "da", "de", "fi", "fr", "es", "ko", "ja", "zh", "zh-hant",
    "ru", "pt", "it", "pl", "uk", "th", "tl", "nl", "sv",
    "id", "ms", "hi", "el", "bn", "he",
})

# Novelty languages — path-prefix routing works but no hreflang or sitemap entries.
# Add new fun languages here as their translations are added.
FUN_LANGS: frozenset = frozenset({
    "eo", "pgl", "tlh",
})

# Klingon is routeable as a novelty/fun locale. Until a vetted Klingon glossary
# is available, it intentionally inherits English UI strings so every page works
# without broken/mixed labels.
TRANSLATIONS.setdefault("tlh", TRANSLATIONS["en"].copy())

# ──────────────────────────────────────────────────────────────────────────────
# Localize internal hrefs inside translation strings.
#
# Many SEO-content strings embed `<a href="/intermediate">…</a>` style links.
# When rendered for a non-English locale, those hrefs must include the language
# prefix (e.g. `/nl/intermediate`) or readers get dumped back into English mid-
# session — a real SEO and UX bug. We rewrite at module load (once per process)
# so per-request rendering stays free.
#
# Rewrite rule: href="/X" → href="/{lang}/X" for every non-English locale,
# UNLESS the path is one that should never carry a language prefix.
import re as _re

# Paths that must NOT be prefixed: backend infra and language-neutral assets.
_NO_PREFIX_PREFIXES = (
    "/api/", "/static/", "/auth/", "/ws/", "/admin/",
    "/info/", "/health", "/set-lang", "/sitemap", "/robots",
    "/favicon", "/ads.txt", "/app-ads.txt", "/.well-known/",
)

# Match href="/path" or href='/path' (but not protocol-relative //, mailto:, etc.)
_HREF_RE = _re.compile(r'''(href\s*=\s*["'])(/[^"'#?\s][^"'#?\s]*)''')


def _localize_hrefs(value: str, lang: str) -> str:
    """Rewrite internal hrefs in `value` to include the /{lang} prefix.

    Already-prefixed paths (e.g. `/de/foo`) and infra paths (`/api/*`, `/static/*`,
    `/info/*`, etc.) are left alone. Designed to be idempotent.
    """
    prefix = f"/{lang}"

    def _sub(m: "_re.Match[str]") -> str:
        attr, path = m.group(1), m.group(2)
        # Already starts with a known locale prefix → leave alone.
        head = path.split("/", 2)
        if len(head) >= 2 and head[1] in TRANSLATIONS:
            return m.group(0)
        # Backend / language-neutral path → leave alone.
        for skip in _NO_PREFIX_PREFIXES:
            if path == skip.rstrip("/") or path.startswith(skip):
                return m.group(0)
        return f"{attr}{prefix}{path}"

    return _HREF_RE.sub(_sub, value)


# Apply the rewrite to every string value in every non-English locale. English
# stays untouched (its href="/X" links are already correct for the English root).
for _lang_code, _strings in TRANSLATIONS.items():
    if _lang_code == "en":
        continue
    for _key, _val in list(_strings.items()):
        if isinstance(_val, str) and 'href' in _val:
            _strings[_key] = _localize_hrefs(_val, _lang_code)

del _lang_code, _strings, _key, _val  # tidy module namespace

# All routeable language codes (real + fun + "en")
SUPPORTED_LANGS: frozenset = frozenset(TRANSLATIONS.keys())


def get_lang(request) -> str:
    # 1. Path-prefix lang injected by lang_prefix_middleware (highest priority)
    lang = getattr(request.state, "lang", None)
    if lang and lang in TRANSLATIONS:
        return lang
    # 2. Query param — backward compat while ?lang= URLs are still indexed
    lang = request.query_params.get("lang")
    if lang and lang in TRANSLATIONS:
        return lang
    # 3. Explicit cookie (user's saved choice)
    lang = request.cookies.get("lang")
    if lang and lang in TRANSLATIONS:
        return lang
    # 4. Subdomain default (e.g. de.minesweeper.org → "de")
    host = request.headers.get("host", "").split(":")[0]
    parts = host.split(".")
    if len(parts) >= 3:
        subdomain = parts[0]
        if subdomain in TRANSLATIONS:
            return subdomain
    return "en"


def get_t(request) -> dict:
    from collections import ChainMap
    lang = get_lang(request)
    if lang == "en":
        return TRANSLATIONS["en"]
    return ChainMap(TRANSLATIONS.get(lang, {}), TRANSLATIONS["en"])
